@pytest.mark.parametrize("method", ["auto", "simple", "wilber", "galil_park", "staggered"])
@pytest.mark.parametrize("cost,name,arr,sols", CASES, ids=[f"{c}-{n}" for c, n, _, _ in CASES])
def test_fixed_solutions(cost, name, arr, sols, method):
    arr = np.array(arr)
    stables = (0, 1, 2, 3) if (cost == "sse" and method == "simple") else (0, 1, 2) if cost == "sse" else (1,)
    for stable in stables:
        for k, sol in sols.items():
            res = univariate_microaggregation(arr.copy(), int(k), method=method, cost=cost, stable=stable)
            np.testing.assert_array_equal(res, sol, f"{name} k={k} stable={stable}")


def test_unsorted_input_and_list():
    x = [5, 1.2, 5, 1.1, 5, 1.4, 5, 1.3]
    for method in ("simple", "wilber", "galil_park", "staggered"):
        res = univariate_microaggregation(x, 3, method=method)
        np.testing.assert_array_equal(res, [1, 0, 1, 0, 1, 0, 1, 0])


def test_invalid_args():
    with pytest.raises(AssertionError):
        univariate_microaggregation([1.0, 2.0], 3)
    with pytest.raises(AssertionError):
        univariate_microaggregation([1.0, 2.0, 3.0], 2, method="bogus")
    with pytest.raises(NotImplementedError):
        univariate_microaggregation([1.0, 2.0, 3.0], 2, cost="bogus")
